package org.example.server.supplier360;
import org.example.server.audit.AuditService;import org.example.server.persistence.JpaNativeRepository;import org.example.server.security.CurrentUser;import org.example.server.util.BusinessClock;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.util.*;
@Service @Transactional public class Supplier360Service{
 private final JpaNativeRepository jdbc; private final AuditService audit; public Supplier360Service(JpaNativeRepository jdbc,AuditService audit){this.jdbc=jdbc;this.audit=audit;}
 @Transactional(readOnly=true) public Supplier360Dtos.Summary summary(int id){CurrentUser.requirePermission("SUPPLIERS.VIEW","View Supplier 360");CurrentUser.requirePermission("PURCHASE.VIEW","View supplier financial summary");var s=supplier(id);BigDecimal out=money("SELECT COALESCE(SUM(GREATEST(COALESCE(total_amount,0)-COALESCE(paid_amount,0),0)),0) FROM purchase_header WHERE supplier_id=? AND UPPER(COALESCE(document_status,'')) NOT IN ('DELETED','CANCELLED','REJECTED')",id);BigDecimal total=money("SELECT COALESCE(SUM(total_amount),0) FROM purchase_header WHERE supplier_id=? AND UPPER(COALESCE(document_status,'')) NOT IN ('DELETED','CANCELLED','REJECTED','PENDING APPROVAL')",id);Long count=jdbc.queryForObject("SELECT COUNT(*) FROM purchase_header WHERE supplier_id=? AND UPPER(COALESCE(document_status,''))<>'DELETED'",Long.class,id);List<Supplier360Dtos.PaymentRow> recent=paymentRows(id,8);BigDecimal last=recent.isEmpty()?BigDecimal.ZERO:recent.getFirst().amount();String date=recent.isEmpty()?"":recent.getFirst().paymentDate();return new Supplier360Dtos.Summary(s,out,count==null?0:count,total,last,date,purchases(id,8),recent);}
 @Transactional(readOnly=true) public List<Supplier360Dtos.PurchaseRow> purchases(int id){CurrentUser.requirePermission("SUPPLIERS.VIEW","View Supplier 360");CurrentUser.requirePermission("PURCHASE.VIEW","View supplier purchases");supplier(id);return purchases(id,500);} private List<Supplier360Dtos.PurchaseRow> purchases(int id,int limit){return jdbc.query("SELECT id,invoice_no,COALESCE(invoice_date::text,''),COALESCE(total_amount,0),COALESCE(paid_amount,0),GREATEST(COALESCE(total_amount,0)-COALESCE(paid_amount,0),0),COALESCE(payment_status,''),COALESCE(document_status,'') FROM purchase_header WHERE supplier_id=? AND UPPER(COALESCE(document_status,''))<>'DELETED' ORDER BY dse_safe_date(invoice_date) DESC,id DESC LIMIT "+limit,(r,i)->new Supplier360Dtos.PurchaseRow(r.getInt(1),r.getString(2),r.getString(3),r.getBigDecimal(4),r.getBigDecimal(5),r.getBigDecimal(6),r.getString(7),r.getString(8)),id);}
 @Transactional(readOnly=true) public List<Supplier360Dtos.PaymentRow> payments(int id){CurrentUser.requirePermission("SUPPLIERS.VIEW","View Supplier 360");CurrentUser.requirePermission("PURCHASE.VIEW","View supplier payments");supplier(id);return paymentRows(id,500);} private List<Supplier360Dtos.PaymentRow> paymentRows(int id,int limit){return jdbc.query("SELECT pr.id,COALESCE(pr.payment_date::text,''),COALESCE(pr.reference_no,''),COALESCE(pr.payment_mode,''),COALESCE(pr.amount,0),COALESCE(ph.invoice_no,''),COALESCE(pr.notes,'') FROM payment_record pr JOIN purchase_header ph ON ph.id=pr.document_id AND pr.document_type='PURCHASE' WHERE ph.supplier_id=? ORDER BY dse_safe_date(pr.payment_date) DESC,pr.id DESC LIMIT "+limit,(r,i)->new Supplier360Dtos.PaymentRow(r.getInt(1),r.getString(2),r.getString(3),r.getString(4),r.getBigDecimal(5),r.getString(6),r.getString(7)),id);}
 @Transactional(readOnly=true) public List<Supplier360Dtos.ContactRow> contacts(int id){CurrentUser.requirePermission("SUPPLIERS.VIEW","View supplier contacts");supplier(id);return jdbc.query("SELECT id,party_id,contact_name,COALESCE(designation,''),COALESCE(department,''),COALESCE(mobile,''),COALESCE(email,''),is_primary,COALESCE(notes,''),row_version,COALESCE(created_by,''),COALESCE(created_at::text,''),COALESCE(updated_by,''),COALESCE(updated_at::text,'') FROM party_contact WHERE party_id=? ORDER BY is_primary DESC,contact_name,id",(r,i)->new Supplier360Dtos.ContactRow(r.getLong(1),r.getInt(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getBoolean(8),r.getString(9),r.getLong(10),r.getString(11),r.getString(12),r.getString(13),r.getString(14)),id);}
 @Transactional public Supplier360Dtos.ContactRow saveContact(int id,Supplier360Dtos.ContactSave d){CurrentUser.requirePermission("SUPPLIERS.EDIT","Manage supplier contacts");supplier(id);if(d==null||blank(d.name()))throw new IllegalArgumentException("Contact name is required");Map<String,Object> before=contactAuditSnapshot(id);if(d.primary())jdbc.update("UPDATE party_contact SET is_primary=FALSE,row_version=row_version+1,updated_by=?,updated_at=? WHERE party_id=? AND is_primary=TRUE"+(d.id()==null?"":" AND id<>?"),d.id()==null?new Object[]{user(),BusinessClock.nowUtcText(),id}:new Object[]{user(),BusinessClock.nowUtcText(),id,d.id()});long cid;String action;if(d.id()==null){cid=jdbc.queryForObject("INSERT INTO party_contact(party_id,contact_name,designation,department,mobile,email,is_primary,notes,created_by,created_at,updated_by,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,id,t(d.name()),t(d.designation()),t(d.department()),t(d.mobile()),t(d.email()),d.primary(),t(d.notes()),user(),BusinessClock.nowUtcText(),user(),BusinessClock.nowUtcText());action="CONTACT_CREATED";}else{int n=jdbc.update("UPDATE party_contact SET contact_name=?,designation=?,department=?,mobile=?,email=?,is_primary=?,notes=?,row_version=row_version+1,updated_by=?,updated_at=? WHERE id=? AND party_id=? AND row_version=?",t(d.name()),t(d.designation()),t(d.department()),t(d.mobile()),t(d.email()),d.primary(),t(d.notes()),user(),BusinessClock.nowUtcText(),d.id(),id,d.rowVersion());if(n!=1)throw new org.example.server.web.ConcurrentEditException("Supplier contact");cid=d.id();action="CONTACT_UPDATED";}audit.logChanges("PARTY",id,action,"Supplier contact • "+t(d.name()),audit.diff(before,contactAuditSnapshot(id)));long x=cid;return contacts(id).stream().filter(c->c.id()==x).findFirst().orElseThrow();}
 @Transactional public void deleteContact(int id,long cid,long rv){CurrentUser.requirePermission("SUPPLIERS.EDIT","Delete supplier contact");supplier(id);Map<String,Object> before=contactAuditSnapshot(id);if(jdbc.update("DELETE FROM party_contact WHERE id=? AND party_id=? AND row_version=?",cid,id,rv)!=1)throw new org.example.server.web.ConcurrentEditException("Supplier contact");audit.logChanges("PARTY",id,"CONTACT_DELETED","Supplier contact #"+cid,audit.diff(before,contactAuditSnapshot(id)));}
 @Transactional(readOnly=true) public List<Supplier360Dtos.NoteRow> notes(int id){CurrentUser.requirePermission("SUPPLIERS.VIEW","View supplier notes");supplier(id);return jdbc.query("SELECT id,party_id,note_text,COALESCE(created_by,''),COALESCE(created_at::text,''),COALESCE(updated_by,''),COALESCE(updated_at::text,''),row_version FROM party_note WHERE party_id=? ORDER BY id DESC",(r,i)->new Supplier360Dtos.NoteRow(r.getLong(1),r.getInt(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getLong(8)),id);}
 @Transactional public Supplier360Dtos.NoteRow saveNote(int id,Supplier360Dtos.NoteSave d){CurrentUser.requirePermission("SUPPLIERS.EDIT","Manage supplier notes");supplier(id);if(d==null||blank(d.note()))throw new IllegalArgumentException("Note is required");Map<String,Object> before=noteAuditSnapshot(id);long nid;String action;if(d.id()==null){nid=jdbc.queryForObject("INSERT INTO party_note(party_id,note_text,created_by,created_at,updated_by,updated_at) VALUES(?,?,?,?,?,?) RETURNING id",Long.class,id,t(d.note()),user(),BusinessClock.nowUtcText(),user(),BusinessClock.nowUtcText());action="NOTE_CREATED";}else{if(jdbc.update("UPDATE party_note SET note_text=?,row_version=row_version+1,updated_by=?,updated_at=? WHERE id=? AND party_id=? AND row_version=?",t(d.note()),user(),BusinessClock.nowUtcText(),d.id(),id,d.rowVersion())!=1)throw new org.example.server.web.ConcurrentEditException("Supplier note");nid=d.id();action="NOTE_UPDATED";}audit.logChanges("PARTY",id,action,"Supplier note #"+nid,audit.diff(before,noteAuditSnapshot(id)));long x=nid;return notes(id).stream().filter(n->n.id()==x).findFirst().orElseThrow();}
 @Transactional public void deleteNote(int id,long nid,long rv){CurrentUser.requirePermission("SUPPLIERS.EDIT","Delete supplier note");supplier(id);Map<String,Object> before=noteAuditSnapshot(id);if(jdbc.update("DELETE FROM party_note WHERE id=? AND party_id=? AND row_version=?",nid,id,rv)!=1)throw new org.example.server.web.ConcurrentEditException("Supplier note");audit.logChanges("PARTY",id,"NOTE_DELETED","Supplier note #"+nid,audit.diff(before,noteAuditSnapshot(id)));}
 private Map<String,Object> contactAuditSnapshot(int partyId){Map<String,Object> out=new LinkedHashMap<>();jdbc.query("SELECT id,contact_name,COALESCE(designation,''),COALESCE(department,''),COALESCE(mobile,''),COALESCE(email,''),is_primary,COALESCE(notes,'') FROM party_contact WHERE party_id=? ORDER BY id",r->{long cid=r.getLong(1);String p="Contact["+cid+"] ";out.put(p+"Name",r.getString(2));out.put(p+"Designation",r.getString(3));out.put(p+"Department",r.getString(4));out.put(p+"Mobile",r.getString(5));out.put(p+"Email",r.getString(6));out.put(p+"Primary",r.getBoolean(7));out.put(p+"Notes",r.getString(8));},partyId);return out;}
 private Map<String,Object> noteAuditSnapshot(int partyId){Map<String,Object> out=new LinkedHashMap<>();jdbc.query("SELECT id,COALESCE(note_text,'') FROM party_note WHERE party_id=? ORDER BY id",r->{out.put("Note["+r.getLong(1)+"]",r.getString(2));},partyId);return out;}
 private Supplier360Dtos.Supplier supplier(int id){var x=jdbc.query("SELECT id,party_code,name,COALESCE(contact_person,''),COALESCE(phone,''),COALESCE(email,''),COALESCE(gstin,''),COALESCE(address,''),COALESCE(opening_balance,0),COALESCE(is_active,1),COALESCE(row_version,0) FROM party_master WHERE id=? AND UPPER(party_type)='SUPPLIER'",(r,i)->new Supplier360Dtos.Supplier(r.getInt(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8),r.getBigDecimal(9),r.getInt(10)!=0,r.getLong(11)),id);if(x.isEmpty())throw new IllegalArgumentException("Supplier not found");return x.getFirst();}
 private String user(){return CurrentUser.require().username();}private BigDecimal money(String q,Object...a){BigDecimal b=jdbc.queryForObject(q,BigDecimal.class,a);return b==null?BigDecimal.ZERO:b;}private static boolean blank(String s){return s==null||s.trim().isBlank();}private static String t(String s){return s==null?"":s.trim();}
}
